const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: Date.now() - startTime
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const analysis = JSON.parse(content);

    // Validate required fields
    const validCategories = ['length', 'accuracy', 'tone', 'speed', 'confirmation', 'detail', 'format', 'other'];
    if (!validCategories.includes(analysis.category)) {
      analysis.category = 'other';
    }

    // Ensure detected_problems is an array
    if (!Array.isArray(analysis.detected_problems)) {
      analysis.detected_problems = [];
    }

    // Ensure confidence is a number between 0 and 1
    if (typeof analysis.confidence !== 'number' || analysis.confidence < 0 || analysis.confidence > 1) {
      analysis.confidence = 0.5;
    }

    return {
      json: {
        success: true,
        analysis: {
          category: analysis.category,
          issue: analysis.issue || null,
          detected_problems: analysis.detected_problems,
          user_preference: analysis.user_preference || null,
          suggested_action: analysis.suggested_action || null,
          confidence: analysis.confidence
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: Date.now() - startTime
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse analysis response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini',
          processing_time_ms: Date.now() - startTime
        }
      }
    };
  }
});

return results;
